import { spaces, machines, panes, terminals, run, openOverlay, exec, hc, theme, shared, setShared, watchFolder, window, layout, pickFolder, notify } from "herdr";

// Spaces that show an OpenRig team: a live terminal there runs `tmux attach -t =<seat>@<rig>`.
function rigSpaces() {
  const map = {};
  for (const k of terminals()) {
    if (k.state !== "live") continue;
    const argv = k.argv ?? [], i = argv.indexOf("attach");
    const rig = i >= 0 && argv[i + 1] === "-t" ? /^=[^@]+@(.+)$/.exec(argv[i + 2] ?? "")?.[1] : null;
    // Labels on another machine omit its "<machine>/" prefix; the app's space ids carry it.
    const pre = k.address.includes("/") ? k.address.slice(0, k.address.indexOf("/") + 1) : "";
    const space = k.labels?.["herdr.space"] ? pre + k.labels["herdr.space"] : null;
    if (rig && space && argv.includes("tmux")) map[space] ??= rig;
  }
  return map;
}

// Like the Spaces header's +, the machine row's + asks for a folder first; cancel makes nothing.
// The picker is this computer's (Windows), so on a WSL machine the chosen folder is translated:
// \\wsl.localhost\<distro>\home\me → /home/me, C:\work → /mnt/c/work. Machines that aren't WSL
// (no $WSL_DISTRO_NAME) keep the old behavior: a new space in that machine's home.
function newSpaceOn(m) {
  if (!m) {
    pickFolder({ prompt: "New space in…" }).then(folder => { if (folder) run("space.new", { folder, machine: "" }); }).catch(() => {});
    return;
  }
  exec("sh", ["-c", 'printf "%s\\n%s" "$WSL_DISTRO_NAME" "$HOME"'], { on: m, timeout: 10000 })
    .then(r => {
      const [distro = "", home = ""] = String(r?.stdout ?? "").split("\n").map(s => s.trim());
      if (!distro) return run("space.new", home.startsWith("/") ? { machine: m, folder: home } : { machine: m });
      return pickFolder({ prompt: `New space on ${m} in…` }).then(picked => {
        if (!picked) return;
        const folder = toWslPath(picked, distro);
        if (folder) run("space.new", { machine: m, folder });
        else notify({ title: "Can't open that folder on " + m, body: `${picked} isn't inside ${distro} or a Windows drive.`, level: "warning" });
      });
    })
    .catch(() => run("space.new", { machine: m }));
}

// A Windows path from the folder picker as a path inside the WSL distro `distro`, or null.
function toWslPath(p, distro) {
  const s = String(p).replace(/\//g, "\\");
  const unc = /^\\\\(?:\?\\UNC\\)?(?:wsl\.localhost|wsl\$)\\([^\\]+)(\\.*)?$/i.exec(s);
  if (unc) return unc[1].toLowerCase() === distro.toLowerCase() ? ((unc[2] ?? "").replace(/\\/g, "/").replace(/\/+$/, "") || "/") : null;
  const drive = /^([A-Za-z]):(\\.*)?$/.exec(s);
  if (drive) return `/mnt/${drive[1].toLowerCase()}${(drive[2] ?? "").replace(/\\/g, "/")}`.replace(/\/+$/, "");
  return null;
}
